import {useMemo} from 'react'
import invariant from 'tiny-invariant'

import type {CustomKey, CustomModel} from '../types'
import {AvailableModel} from './AvailableModel'
import {EmptyState} from './EmptyState'

export function AvailableModels({
  publicKey,
  customKeys,
  customModels,
  onUpdateModels,
}: {
  publicKey: string
  customKeys: CustomKey[]
  customModels: CustomModel[]
  onUpdateModels: () => void
}) {
  const customKeysById = useMemo(() => new Map(customKeys.map(key => [key.id, key])), [customKeys])

  return customKeys.length > 0 ? (
    <>
      {customModels.map(model => {
        const customKey = customKeysById.get(model.customKeyId)
        invariant(customKey, `Custom key with id ${model.customKeyId} not found for model ${model.slug}`)

        return <AvailableModel key={model.id} customKey={customKey} model={model} onUpdateModel={onUpdateModels} />
      })}
    </>
  ) : (
    <EmptyState onSuccess={onUpdateModels} publicKey={publicKey} />
  )
}

try{ AvailableModels.displayName ||= 'AvailableModels' } catch {}