function FeaturesForDataRetention({
  copilot_for_dotcom_visible,
  showCopilotInTheCLI,
}: {
  copilot_for_dotcom_visible: boolean | null
  showCopilotInTheCLI: boolean | null
}) {
  const features = []
  if (showCopilotInTheCLI) features.push('Copilot in the CLI')
  if (copilot_for_dotcom_visible) features.push('Copilot in GitHub.com')
  features.push('Copilot Chat in GitHub Mobile')
  let message = ''
  if (features.length === 1) {
    message = `Enabling ${features[0]} will collect additional data and updated`
  } else if (features.length === 2) {
    message = `Enabling ${features[0]} and ${features[1]} will collect additional data and updated`
  } else if (features.length === 3) {
    message = `Enabling ${features[0]}, ${features[1]} and ${features[2]} will collect additional data and updated`
  }

  return (
    <>
      {message && (
        <>
          {message}{' '}
          <Link
            href="https://github.com/customer-terms/github-copilot-product-specific-terms"
            className="Link--inTextBlock"
            inline
          >
            Product Terms
          </Link>{' '}
          apply.{' '}
        </>
      )}
    </>
  )
}

export function PoliciesPageEntrypointLegacy() {
  const payload = useRoutePayload<CopilotForBusinessPoliciesPayload>()
  return <PoliciesPage payload={payload} />
}

export function PoliciesPageEntrypoint() {
  const {data: payload} = useRouteQuery(copilotForBusinessPoliciesRoute, 'mainQuery')
  return <PoliciesPage payload={payload} />
}

export function PoliciesPage({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const copilot_bing_visible = payload.bing_github_chat.visible
  const copilot_for_dotcom_visible = payload.copilot_for_dotcom.visible
  const show_copilot_extensions_policy = useFeatureFlag('copilot_extension_access')
  const show_copilot_telemetry_policy = useFeatureFlag('copilot_private_telemetry_access')
  const showCopilotDesktopPolicy = payload.desktop.visible
  const showEditorPreviewFeatures = payload.editor_preview_features.visible
  const showAgentMode = payload.agent_mode.visible
  const showInsightsPolicy = payload.insights.visible
  const showMcpPolicy = payload.mcp.visible
  const showMcpRegistry = payload.mcp_registry.visible
  const showMcpRegistryAccess = payload.mcp_registry_access.visible
  const showOveragesPolicy = payload.overages.visible
  const showCodeReviewPolicy = payload.code_review.visible
  const showSparkPolicy = payload.spark.visible
  const showSweAgentPolicy = payload.swe_agent.visible
  const showCopilotInTheCLI = !useFeatureFlag('copilot_agent_cli_public_preview')
  const showCopilotCLIBeta = !useFeatureFlag('copilot_agent_cli_ga')

  const {enterprise_name, enterprise_slug, copilot_plan: plan, docsUrls, org_name} = payload

  const mcp = useMcpPolicyState(payload)

  const hasBannerPortal = showMcpRegistry || showMcpRegistryAccess
  return (
    <>
      {hasBannerPortal && mcp.bannerMessage?.message && (
        <BannerPortal
          message={mcp.bannerMessage.message}
          variant={mcp.bannerMessage.variant}
          onDismiss={mcp.dismissBanner}
        />
      )}
      <PageHeading name="GitHub Copilot" />
      <div className={clsx(styles.topBox, 'mb-3')}>
        <span className={clsx(styles.muted, 'mb-3')}>
          You can manage policies and grant access to Copilot features for all members with access.
          <br />
          Note that users from other organizations may gain access if permitted by their administrators.
        </span>
        {enterprise_name && enterprise_slug && (
          <span className={clsx(styles.muted, 'mr-2', 'mb-3')} data-testid="cfb-managed-organization-enterprise">
            <ShieldLockIcon /> Managed by{' '}
            <Link inline href={`/enterprises/${enterprise_slug}`}>
              {enterprise_name}
            </Link>
          </span>
        )}
      </div>

      {/*============== START OF BILLING POLICIES SECTION ==============*/}
      {/*
        today, overages is the only billing policy
        if more billing policies are added in the future, the conditions need to be modified/removed
      */}
      {showOveragesPolicy && (
        <Box
          data-hpc
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--stack-gap-normal)',
            marginBottom: 3,
          }}
        >
          <SectionHeading name="Billing" />
          <BoxSection>
            <OveragesPolicy enterprise_name={enterprise_name} org_name={org_name} payload={payload} />
          </BoxSection>
        </Box>
      )}
      {/*============== END OF BILLING POLICIES SECTION ==============*/}

      {/*============== START OF FEATURES POLICIES SECTION ==============*/}
      <Box
        data-hpc
        sx={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--stack-gap-normal)',
          marginBottom: 3,
        }}
      >
        <SectionHeading name="Features" />
        <BoxSection>
          {copilot_for_dotcom_visible && <CopilotForDotcomPolicy payload={payload} />}
          {showSparkPolicy && <GeneralPolicy payload={payload} policy={payload.spark} />}
          <GeneralPolicy payload={payload} policy={payload.editor_chat} />
          {showEditorPreviewFeatures && <GeneralPolicy payload={payload} policy={payload.editor_preview_features} />}
          {showAgentMode && <GeneralPolicy payload={payload} policy={payload.agent_mode} />}
          <GeneralPolicy payload={payload} policy={payload.mobile_chat} />
          <CopilotCLIPolicy
            payload={payload}
            showCopilotInTheCLI={showCopilotInTheCLI}
            showBeta={!showCopilotInTheCLI && showCopilotCLIBeta}
          />
          {showCopilotDesktopPolicy && <GeneralPolicy payload={payload} policy={payload.desktop} />}
          {show_copilot_extensions_policy && <CopilotExtensionsPolicy payload={payload} />}
          {copilot_bing_visible && <GeneralPolicy payload={payload} policy={payload.bing_github_chat} />}
          <GeneralPolicy payload={payload} policy={payload.copilot_usage_metrics_policy} />
          {showInsightsPolicy && <GeneralPolicy payload={payload} policy={payload.insights} />}
          {showCodeReviewPolicy && <CopilotCodeReviewPolicy payload={payload} />}
          {showSweAgentPolicy && <GeneralPolicy payload={payload} policy={payload.swe_agent} />}

          {/*==== MCP Policies section ====*/}

          {showMcpPolicy && (
            <McpPolicy
              policy={payload.mcp}
              onSelect={mcp.mcpOptions.onSelect}
              options={mcp.mcpOptions.options}
              selected={mcp.mcpOptions.selected}
              loading={mcp.mcpOptions.loading}
            />
          )}
          {showMcpRegistry && (
            <McpRegistry
              mcpRegistry={payload.mcp_registry}
              value={mcp.registryUrl}
              onChange={mcp.setRegistryUrl}
              loading={mcp.loading}
              onSubmit={e => {
                e.preventDefault()
                mcp.submitRegistryUrl()
              }}
              onDelete={() => {
                mcp.setRegistryUrl('')
                mcp.submitRegistryUrl('')
              }}
              inputDisabled={mcp.mcpPolicyDisabled || mcp.loading || !payload.mcp_registry.configurable}
            />
          )}
          {showMcpRegistryAccess && (
            <McpRegistryAccess
              options={mcp.mcpRegistryAccessOptions.options}
              selected={mcp.registryAccess}
              onSelect={mcp.submitRegistryAccess}
              loading={mcp.loading}
              policy={payload.mcp_registry_access}
              inputDisabled={
                !payload.mcp_registry_access.configurable ||
                mcp.mcpPolicyDisabled ||
                mcp.loading ||
                !mcp.registryUrl ||
                !isValidUrl(mcp.registryUrl)
              }
            />
          )}
        </BoxSection>
      </Box>
      {/*============== END OF FEATURES POLICIES SECTION ==============*/}

      {/*============== START OF PRIVACY POLICIES SECTION ==============*/}
      <Box
        data-hpc
        sx={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--stack-gap-normal)',
          marginBottom: 3,
        }}
      >
        <SectionHeading name="Duplicate Detection Filter" />
        <BoxSection>
          <GeneralPolicy payload={payload} policy={payload.snippy} />
          {show_copilot_telemetry_policy && <CopilotTelemetryPolicy payload={payload} />}
        </BoxSection>
      </Box>
      {/*============== END OF PRIVACY POLICIES SECTION ==============*/}

      <Box
        data-hpc
        sx={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--stack-gap-normal)',
          marginBottom: 3,
        }}
      >
        <Text as="p" sx={{color: 'fg.muted'}} data-testid="cb-policies-footnotes">
          {' '}
          {plan !== 'enterprise' && (
            <FeaturesForDataRetention
              copilot_for_dotcom_visible={copilot_for_dotcom_visible}
              showCopilotInTheCLI={showCopilotInTheCLI}
            />
          )}
          If preview features are enabled, you agree to{' '}
          <Link href="https://docs.github.com/site-policy/github-terms/github-copilot-pre-release-license-terms" inline>
            pre-release terms
          </Link>
          . For more information about the data your organization receives regarding your use of GitHub Copilot, please
          review{' '}
          <Link href={docsUrls.generalPrivacyStatement} inline>
            GitHub&apos;s Privacy Statement
          </Link>
          .
        </Text>
      </Box>
    </>
  )
}

function CopilotForDotcomPolicy({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const isCopilotChatGA = useFeatureFlag('copilot_chat_dotcom_ga')
  const showCodeReviewPolicy = payload.code_review.visible
  const data = payload.copilot_for_dotcom
  const {copilot_plan: plan} = payload
  const isEnterprisePlan = plan === 'enterprise'

  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: data.options,
    controls: data.manages,
  })

  const disabled = !data.configurable

  // Determines what list separate to use depending on which features can be enabled by the organization
  const copilotCodeReviewListSeparator = isEnterprisePlan ? ', ' : ', and'

  return (
    <Box sx={{display: 'flex', flexDirection: 'column', width: '100%'}}>
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: selected?.value === 'enabled' ? 'start' : 'center',
        }}
      >
        <div data-testid="cfb-policies-dotcom-bundle-feature">
          <PreviewFeatureHeading title="Copilot in GitHub.com" beta={!isEnterprisePlan && !isCopilotChatGA} />
          {showCodeReviewPolicy ? (
            <div>
              If enabled, members of this organization can use{' '}
              <Link
                href="https://docs.github.com/copilot/github-copilot-enterprise/copilot-chat-in-github/about-github-copilot-chat"
                inline
              >
                Copilot Chat in GitHub.com
              </Link>
              {isEnterprisePlan && (
                <>
                  {' and '}
                  <Link
                    href="https://docs.github.com/enterprise-cloud@latest/copilot/github-copilot-enterprise/copilot-docset-management/about-copilot-docset-management"
                    inline
                  >
                    knowledge base search
                  </Link>
                </>
              )}
              .
            </div>
          ) : (
            <div>
              If enabled, members of this organization can use{' '}
              <Link
                href="https://docs.github.com/copilot/github-copilot-enterprise/copilot-chat-in-github/about-github-copilot-chat"
                inline
              >
                Copilot Chat in GitHub.com
              </Link>
              ,{' '}
              <Link
                href="https://docs.github.com/copilot/github-copilot-enterprise/copilot-pull-request-summaries/about-copilot-pull-request-summaries"
                inline
              >
                Copilot for pull requests
              </Link>
              {copilotCodeReviewListSeparator}{' '}
              <Link
                href="https://docs.github.com/en/enterprise-cloud@latest/copilot/using-github-copilot/code-review/using-copilot-code-review"
                inline
              >
                Copilot code review
              </Link>
              {isEnterprisePlan && (
                <>
                  {', and '}
                  <Link
                    href="https://docs.github.com/enterprise-cloud@latest/copilot/github-copilot-enterprise/copilot-docset-management/about-copilot-docset-management"
                    inline
                  >
                    knowledge base search
                  </Link>
                </>
              )}
              .
            </div>
          )}
          {selected?.value === 'enabled' && <UserFeedbackPolicy payload={payload} />}
          {selected?.value === 'enabled' && <CopilotForDotcomBetaFeaturesPolicy payload={payload} />}
        </div>
        {disabled ? (
          <Box
            as="span"
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              gap: 1,
            }}
            data-testid="cfb-policies-dotcom-feature-locked"
          >
            <ShieldLockIcon /> {selected?.title ?? 'Disabled'}
          </Box>
        ) : (
          <ActionMenuButton
            title={selected?.title ?? 'Disabled'}
            options={options}
            onSelect={onSelect}
            disabled={disabled}
            loading={loading}
            data-testid="cfb-policies-dotcom-bundle-feature-button"
          />
        )}
      </Box>
    </Box>
  )
}

