import invariant from 'tiny-invariant'

import azureLogo from './assets/azureai.svg'
import openaiLogoBlack from './assets/openai-black.svg'
import openaiLogoWhite from './assets/openai-white.svg'

export type ProviderItem = (typeof providerList)[number]
export type Provider = ProviderItem['key']

export const providerList = [
  {
    key: 'openai',
    name: 'OpenAI',
    logo: {
      // Which logo to use for light mode
      light: openaiLogoBlack,
      dark: openaiLogoWhite,
    },
  },
  {
    key: 'azureai',
    name: 'Azure AI',
    // If there is no dark mode logo, it will use the light logo in dark mode
    logo: {light: azureLogo, dark: undefined},
  },
] as const

export function getProviderFor(key: Provider): ProviderItem {
  const provider = providerList.find(p => p.key === key)
  invariant(provider, `Provider with key "${key}" not found`)
  return provider
}
