import {testIdProps} from '@github-ui/test-id-props'
import {useSearchParams} from '@github-ui/use-navigate'
import {useLocation} from '@github-ui/react-router'
import {UnderlineNav} from '@primer/react'
import {type ReactNode, useCallback, useMemo, useState} from 'react'

export type SelectedModelType = 'default' | 'custom'

interface DefaultOrCustomModelSelectorProps {
  children: (selectedModelType: SelectedModelType) => ReactNode
}

const modelTypeUrlParam = 'tab'

export function DefaultOrCustomModelSelector({children}: DefaultOrCustomModelSelectorProps) {
  const [searchParams, setSearchParams] = useSearchParams()
  const {pathname} = useLocation()
  const [selectedModelType, setSelectedModelType] = useState<SelectedModelType>(
    searchParams.get(modelTypeUrlParam) === 'custom' ? 'custom' : 'default',
  )
  const searchParamsForCustom = useMemo(() => {
    const result = new URLSearchParams(searchParams)
    result.set(modelTypeUrlParam, 'custom')
    return result
  }, [searchParams])
  const onDefaultSelect = useCallback(() => {
    setSelectedModelType('default')
    const newSearchParams = new URLSearchParams(searchParams)
    newSearchParams.delete(modelTypeUrlParam)
    setSearchParams(newSearchParams, {replace: true})
  }, [searchParams, setSearchParams])
  const onCustomSelect = useCallback(() => {
    setSelectedModelType('custom')
    setSearchParams(searchParamsForCustom, {replace: true})
  }, [searchParamsForCustom, setSearchParams])

  return (
    <div {...testIdProps('default-or-custom-model-selector')}>
      <div className="mb-3">
        <UnderlineNav aria-label="Default/Custom model menu" variant="flush">
          <UnderlineNav.Item
            onSelect={onDefaultSelect}
            href={pathname}
            aria-current={selectedModelType === 'default' ? 'page' : undefined}
          >
            Default models
          </UnderlineNav.Item>
          <UnderlineNav.Item
            onSelect={onCustomSelect}
            href={`${pathname}?${searchParamsForCustom}`}
            aria-current={selectedModelType === 'custom' ? 'page' : undefined}
          >
            Custom models
          </UnderlineNav.Item>
        </UnderlineNav>
      </div>
      {children(selectedModelType)}
    </div>
  )
}

try{ DefaultOrCustomModelSelector.displayName ||= 'DefaultOrCustomModelSelector' } catch {}