import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useCallback, useState} from 'react'
import {createURLParams} from '../helpers/query'

export const orgBudgetsUrl = (org: string) => `/organizations/${org}/settings/billing/budgets`
export const enterpriseBudgetsUrl = (enterprise: string) => `/enterprises/${enterprise}/billing/budgets`

type OverageUpdateParams = {
  slug: string
  isOrg: boolean
}

/**
 * API config types
 */
type MethodsWithBody = 'POST' | 'PUT'
type ReqConfig<Req> = {method: 'GET' | 'DELETE'} | {method: MethodsWithBody; body?: Req}

const SERVER_ERROR_MSG = 'Something went wrong'

export const useBillingApiMethod = (slug: string, isOrg: boolean) => {
  const [error, setError] = useState<string>('')

  const callApi = useCallback(
    async function callApi<Res = unknown, Req = unknown>(endpoint: string, configs: ReqConfig<Req>): Promise<Res> {
      const body: Req | undefined =
        (configs.method === 'POST' || configs.method === 'PUT') && 'body' in configs ? configs.body : undefined

      const base = isOrg ? `/organizations/${slug}/settings/billing/` : `/enterprises/${slug}/settings/billing/`

      try {
        const response = await verifiedFetchJSON(`${base}${endpoint}`, {
          method: configs.method,
          body,
        })

        let json: unknown
        try {
          json = await response.json()
        } catch {
          json = undefined
        }

        if (response.ok) {
          setError('')
          return json as Res
        }

        const message = SERVER_ERROR_MSG
        setError(message)
        throw new Error(message)
      } catch (e) {
        const message = e instanceof Error ? e.message : SERVER_ERROR_MSG
        setError(message)
        throw e
      }
    },
    [isOrg, slug],
  )

  return {error, callApi}
}

/**
 * Hook to update overage policy
 */
export function useOverageUpdate({slug, isOrg}: OverageUpdateParams) {
  const {callApi} = useBillingApiMethod(slug, isOrg)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string>('')
  const [apiResponse, setApiResponse] = useState<unknown>(null)

  const updateOveragePolicy = useCallback(
    async (name: string, type: 'sku' | 'product', val: boolean) => {
      setLoading(true)
      const params = createURLParams({
        name,
        enabled: val,
        type,
      })
      try {
        const response = await callApi(`update_policy?${params}`, {method: 'PUT', body: {}})
        setApiResponse(response)
        setError('')
      } catch (e) {
        setError(e instanceof Error ? e.message : SERVER_ERROR_MSG)
      } finally {
        setLoading(false)
      }
    },
    [callApi],
  )

  return {updateOveragePolicy, apiResponse, loading, error}
}
