import {encrypt} from '@github-ui/encryption'
import {encode} from '@github-ui/encryption/utils'
import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useMutation} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {Dialog, FormControl, Stack, TextInput} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import {type FormEvent, type RefObject, startTransition, useCallback, useId, useMemo, useRef, useState} from 'react'
import * as z from 'zod'

import {useCurrentOrg} from '../contexts/CurrentOrgContext'
import {getErrorMessageFromResponse} from '../helpers/extract-errors'
import {getFormValidationNode, type ValidationKind, validationKindFromZodError} from '../helpers/Validation'
import {useAPIKey} from '../hooks/use-api-key'
import {getProviderFor, type Provider} from '../providers/config'
import {ProviderPicker} from '../providers/ProviderPicker'
import type {CreateCustomKeyMutationData} from '../types'
import styles from './AddEditDialog.module.css'
import {providerFields, providerSchema} from './providers'
import type {ProviderAdditionalData} from './providers/types'

const base = z.lazy(() =>
  z.object({
    provider: z.string().nonempty('A provider must be selected'),
    name: z.string().nonempty('A name is required'),
    api_key: z.string().nonempty('An API key is required'),
  }),
)

const formSchema = z.lazy(() =>
  z.discriminatedUnion('provider', [base.unwrap().extend(providerSchema[0]), base.unwrap().extend(providerSchema[1])]),
)

export function AddKeyDialog({
  publicKey,
  anchorRef,
  onCancel,
  onSuccess,
}: {
  publicKey: string
  anchorRef?: RefObject<HTMLElement>
  onCancel: () => void
  onSuccess: (data: CreateCustomKeyMutationData) => void
}) {
  const id = useId()
  const nameValidationId = `name-validation-${id}`
  const nameCaptionId = `name-caption-${id}`
  const apiKeyValidationId = `api_key-validation-${id}`

  const [selectedProvider, setSelectProvider] = useState<Provider>('openai')
  const [validation, setValidation] = useState<Record<string, ValidationKind>>()
  const [apiKey, setApiKey] = useAPIKey(publicKey)
  const additionalData = useRef<ProviderAdditionalData>(undefined)

  const org = useCurrentOrg()

  const {mutate, isPending} = useMutation<CreateCustomKeyMutationData, ResponseError, z.infer<typeof formSchema>>({
    async mutationFn(variables) {
      const encryptedKey = await encrypt(publicKey, variables.api_key)
      variables.api_key = encode(encryptedKey)

      const r = await reactFetchJSON(`/organizations/${org}/settings/copilot/custom-models`, {
        method: 'POST',
        body: variables,
      })
      if (!r.ok) {
        throw new ResponseError('Failed to add API key', r)
      }
      return r.json() as Promise<CreateCustomKeyMutationData>
    },
  })

  function onSubmitHandler(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const formData = new FormData(event.currentTarget)
    const payload = Object.fromEntries(formData.entries()) as Record<string, unknown>
    Object.assign(payload, additionalData.current)

    const {success, data, error} = formSchema.safeParse(payload)
    if (!success) {
      setValidation(validationKindFromZodError(error))
      return
    }

    startTransition(() => {
      setValidation(undefined)
      mutate(data, {
        onSuccess,
        async onError(mutationError) {
          const message = await getErrorMessageFromResponse(mutationError)

          setValidation({
            __general: {error: message || 'An unexpected error occurred. Please try again later.'},
          })
        },
      })
    })
  }

  const ProviderFields = useMemo(() => {
    return providerFields[selectedProvider]
  }, [selectedProvider])

  const onSelectProvider = useCallback((provider: Provider) => {
    setSelectProvider(provider)
    additionalData.current = undefined
  }, [])

  const onSetAdditionalData = useCallback((data: ProviderAdditionalData) => {
    additionalData.current = data
  }, [])

  return (
    <Dialog
      title="Add API key"
      onClose={onCancel}
      position="right"
      width="large"
      className={styles.AddEditDialogLayout}
      returnFocusRef={anchorRef}
      footerButtons={[
        {content: 'Cancel', buttonType: 'default', onClick: onCancel},
        {
          content: 'Save',
          buttonType: 'primary',
          type: 'submit',
          form: `${id}-form`,
          loading: isPending,
          loadingAnnouncement: 'Adding custom key',
        },
      ]}
    >
      <Stack
        as="form"
        id={`${id}-form`}
        className="height-full"
        onSubmit={onSubmitHandler as unknown as React.FormEventHandler<HTMLDivElement>}
      >
        {validation?.__general && (
          <Banner role="banner" title="Error" variant="critical" hideTitle description={validation.__general.error} />
        )}

        <FormControl id={`${id}-provider`} disabled={isPending}>
          <ProviderPicker
            id={`${id}-provider`}
            selected={selectedProvider}
            onSelected={onSelectProvider}
            disabled={isPending}
          />
          <FormControl.Label>Provider</FormControl.Label>
          <input type="hidden" name="provider" value={selectedProvider} />
        </FormControl>

        <FormControl required disabled={isPending}>
          <FormControl.Label>Name</FormControl.Label>
          <TextInput
            name="name"
            data-1p-ignore
            placeholder={`${getProviderFor(selectedProvider).name}_custom_key`}
            className="width-full"
            aria-describedby={`${nameValidationId} ${nameCaptionId}`}
            autoComplete="off"
          />
          {getFormValidationNode(validation?.name, nameValidationId)}
          <FormControl.Caption id={nameCaptionId}>Models provided will be available under this key</FormControl.Caption>
        </FormControl>

        <FormControl required disabled={isPending}>
          <FormControl.Label>API key</FormControl.Label>
          <TextInput
            name="api_key"
            data-1p-ignore
            type="password"
            autoComplete="new-password"
            className="width-full"
            aria-describedby={apiKeyValidationId}
            onBlur={e => setApiKey(e.currentTarget.value)}
          />
          {getFormValidationNode(validation?.api_key, apiKeyValidationId)}
        </FormControl>

        <ProviderFields
          apiKey={apiKey}
          validation={validation}
          setValidation={setValidation}
          isPending={isPending}
          onSetAdditionalData={onSetAdditionalData}
        />
      </Stack>
    </Dialog>
  )
}

try{ AddKeyDialog.displayName ||= 'AddKeyDialog' } catch {}
try{ ProviderFields.displayName ||= 'ProviderFields' } catch {}