import {clsx} from 'clsx'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {ShieldLockIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import {Box, Text} from '@primer/styled-react'
import {BoxSection, PageHeading} from '../traditional/components/Ui'
import type {CopilotForBusinessModelsPayload} from '../types'
import styles from './Policies.module.css'
import GeneralPolicy from '../components/GeneralPolicy'
import {useMemo} from 'react'
import {testIdProps} from '@github-ui/test-id-props'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {copilotForBusinessModelsRoute} from './models-route'
import {DefaultOrCustomModelSelector} from '../components/DefaultOrCustomModelSelector'
import {CustomModelsIndex} from '@github-ui/copilot-byok-settings/routes/CustomModelsIndex'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

function FeaturesForDataRetention({
  copilot_for_dotcom_visible,
  showCopilotInTheCLI,
}: {
  copilot_for_dotcom_visible: boolean | null
  showCopilotInTheCLI: boolean | null
}) {
  const features = []
  if (showCopilotInTheCLI) features.push('Copilot in the CLI')
  if (copilot_for_dotcom_visible) features.push('Copilot in GitHub.com')
  features.push('Copilot Chat in GitHub Mobile')
  let message = ''
  if (features.length === 1) {
    message = `Enabling ${features[0]} will collect additional data and updated`
  } else if (features.length === 2) {
    message = `Enabling ${features[0]} and ${features[1]} will collect additional data and updated`
  } else if (features.length === 3) {
    message = `Enabling ${features[0]}, ${features[1]} and ${features[2]} will collect additional data and updated`
  }

  return (
    <>
      {message && (
        <>
          {message}{' '}
          <Link
            href="https://github.com/customer-terms/github-copilot-product-specific-terms"
            className="Link--inTextBlock"
            inline
          >
            Product Terms
          </Link>{' '}
          apply.{' '}
        </>
      )}
    </>
  )
}

// List of models in the order they should be displayed.
const models = [
  'a_chat',
  'a_f',
  'afos',
  'al',
  'aofo',
  'g_chat',
  'g_tf',
  'gtff',
  'o1',
  'o3',
  'o_ff',
  'o_fm',
  'o_f',
  'o_t',
  'ofo',
  'obmb',
  'ofct',
  'obmw',
  'grok_code',
] satisfies Array<keyof CopilotForBusinessModelsPayload>

export function ModelsPageEntrypointLegacy() {
  const payload = useRoutePayload<CopilotForBusinessModelsPayload>()
  return <ModelsPageWrapper payload={payload} />
}

export function ModelsPageEntrypoint() {
  const {data: payload} = useRouteQuery(copilotForBusinessModelsRoute, 'mainQuery')
  return <ModelsPageWrapper payload={payload} />
}

function ModelsPageWrapper({payload}: {payload: CopilotForBusinessModelsPayload}) {
  const showCopilotCustomModels = useFeatureFlag('copilot_byok')
  const headingText = showCopilotCustomModels ? 'Copilot models' : 'GitHub Copilot models'

  return (
    <>
      <PageHeading name={headingText} />
      {showCopilotCustomModels ? (
        <DefaultOrCustomModelSelector>
          {selectedModelType =>
            selectedModelType === 'custom' ? (
              <CustomModelsIndex
                org={payload.org_name}
                enterpriseName={payload.enterprise_name}
                enterpriseSlug={payload.enterprise_slug}
              />
            ) : (
              <ModelsPage payload={payload} />
            )
          }
        </DefaultOrCustomModelSelector>
      ) : (
        <ModelsPage payload={payload} />
      )}
    </>
  )
}

function ModelsPage({payload}: {payload: CopilotForBusinessModelsPayload}) {
  const {
    enterprise_name,
    enterprise_slug,
    copilot_plan: plan,
    docsUrls,
    copilot_for_dotcom_visible,
    ...modelsPayload
  } = payload
  const showCopilotCustomModels = useFeatureFlag('copilot_byok')
  const showCopilotInTheCLI = !useFeatureFlag('copilot_agent_cli_public_preview')
  const introPhrasing = showCopilotCustomModels ? 'Manage' : 'You can manage'

  const filteredModels = useMemo(() => {
    return models
      .map(model => {
        const data = modelsPayload[model]
        if (!data) return null
        return data.visible ? data : null
      })
      .filter(model => model !== null)
  }, [modelsPayload])

  return (
    <>
      <div {...testIdProps('models-page-intro')} className={clsx(styles.topBox, 'mb-3')}>
        <span className={clsx(styles.muted)}>
          {introPhrasing} policies and grant access to Copilot models for all members with access.
          <br />
          Note that users from other organizations may gain access if permitted by their administrators.
        </span>
        {enterprise_name && enterprise_slug && (
          <span className={clsx(styles.muted, 'mr-2')} {...testIdProps('cfb-managed-organization-enterprise')}>
            <ShieldLockIcon /> Managed by{' '}
            <Link inline href={`/enterprises/${enterprise_slug}`}>
              {enterprise_name}
            </Link>
          </span>
        )}
      </div>
      <Box
        data-hpc
        sx={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--stack-gap-normal)',
        }}
      >
        <BoxSection>
          {filteredModels.map(model => (
            <GeneralPolicy payload={payload} key={model.manages} policy={model} />
          ))}
        </BoxSection>
        <Text as="p" sx={{color: 'fg.muted'}} data-testid="cb-policies-footnotes">
          {' '}
          {plan !== 'enterprise' && (
            <FeaturesForDataRetention
              copilot_for_dotcom_visible={copilot_for_dotcom_visible}
              showCopilotInTheCLI={showCopilotInTheCLI}
            />
          )}
          If preview features are enabled, you agree to{' '}
          <Link href="https://docs.github.com/site-policy/github-terms/github-copilot-pre-release-license-terms" inline>
            pre-release terms
          </Link>
          . For more information about the data your organization receives regarding your use of GitHub Copilot, please
          review{' '}
          <Link href={docsUrls.generalPrivacyStatement} inline>
            GitHub&apos;s Privacy Statement
          </Link>
          .
        </Text>
      </Box>
    </>
  )
}

try{ FeaturesForDataRetention.displayName ||= 'FeaturesForDataRetention' } catch {}
try{ ModelsPageEntrypointLegacy.displayName ||= 'ModelsPageEntrypointLegacy' } catch {}
try{ ModelsPageEntrypoint.displayName ||= 'ModelsPageEntrypoint' } catch {}
try{ ModelsPageWrapper.displayName ||= 'ModelsPageWrapper' } catch {}
try{ ModelsPage.displayName ||= 'ModelsPage' } catch {}