import {getQueryClient} from '@github-ui/react-core/query-client'
import {testIdProps} from '@github-ui/test-id-props'
import {ShieldLockIcon} from '@primer/octicons-react'
import {Link, SegmentedControl, Stack} from '@primer/react'
import {useCallback, useState} from 'react'

import {AddCustomKeyButton} from '../../components/AddCustomKeyButton'
import {ApiKeys} from '../../components/ApiKeys'
import {AvailableModels} from '../../components/AvailableModels'
import {CurrentOrgProvider} from '../../contexts/CurrentOrgContext'
import {PageBannerOutlet} from '../../contexts/PageBannerContext'
import {useCustomModelsQuery} from '../../queries/use-custom-models-query'
import type {CustomModelsIndexPayload, CustomModelsIndexTabs} from '../../types'
import styles from './CustomModelsIndex.module.css'

interface CustomModelsIndexProps {
  org: CustomModelsIndexPayload['orgDisplayLogin']
  enterpriseName: string | null
  enterpriseSlug: string | null
}

export function CustomModelsIndex({enterpriseName, enterpriseSlug, org}: CustomModelsIndexProps) {
  const {data, isLoading, error, queryKey} = useCustomModelsQuery({org})

  if (isLoading) {
    return <div>Loading custom models...</div>
  }

  if (error) {
    return <div>Error loading custom models: {error.message}</div>
  }

  return (
    <CurrentOrgProvider value={org}>
      <PageBannerOutlet />
      <p className="color-fg-muted">
        Add API keys from AI model providers to register custom third-party models. Once added, you can enable custom
        models to be used with specific GitHub features.
      </p>
      <p className="color-fg-muted">
        When using these models, GitHub will share your data, including code, with the third-party model provider using
        your provided API key. Use of the model is further subject to the terms and privacy policy of the third-party
        model provider.
      </p>
      {enterpriseName && enterpriseSlug && (
        <div className="mb-3 color-fg-muted" {...testIdProps('cfb-managed-organization-enterprise')}>
          <ShieldLockIcon /> Managed by{' '}
          <Link inline href={`/enterprises/${enterpriseSlug}`}>
            {enterpriseName}
          </Link>
        </div>
      )}
      {data?.enabled ? <CustomKeysTabs data={data} queryKey={queryKey} /> : <EnterpriseDisabledMessage />}
    </CurrentOrgProvider>
  )
}

function CustomKeysTabs({
  data: {customModels, customKeys, publicKey},
  queryKey,
}: {
  data: CustomModelsIndexPayload
  queryKey: string[]
}) {
  const [selectedTab, setSelectedTab] = useState<CustomModelsIndexTabs>('keys')
  const hasKeys = customKeys.length > 0

  const onRefresh = useCallback(() => {
    void getQueryClient().invalidateQueries({queryKey})
  }, [queryKey])

  return (
    <div className="border rounded-2 overflow-hidden">
      <div className={styles.segmentedControlAndActions}>
        <SegmentedControl aria-label="Custom models navigation">
          <SegmentedControl.Button onClick={() => setSelectedTab('keys')} selected={selectedTab === 'keys'}>
            API keys
          </SegmentedControl.Button>
          <SegmentedControl.Button onClick={() => setSelectedTab('models')} selected={selectedTab === 'models'}>
            Added models
          </SegmentedControl.Button>
        </SegmentedControl>
        {hasKeys && <AddCustomKeyButtonShowRoute publicKey={publicKey} queryKey={queryKey} />}
      </div>
      <Stack className={styles.stack} gap="none">
        {selectedTab === 'keys' ? (
          <ApiKeys customKeys={customKeys} publicKey={publicKey[1]} onRefresh={onRefresh} />
        ) : (
          <AvailableModels
            customKeys={customKeys}
            publicKey={publicKey[1]}
            customModels={customModels}
            onUpdateModels={onRefresh}
          />
        )}
      </Stack>
    </div>
  )
}

function AddCustomKeyButtonShowRoute({
  publicKey,
  queryKey,
}: {
  publicKey: CustomModelsIndexPayload['publicKey']
  queryKey: string[]
}) {
  const onSuccess = useCallback(() => {
    void getQueryClient().invalidateQueries({queryKey})
  }, [queryKey])

  return <AddCustomKeyButton onSuccess={onSuccess} publicKey={publicKey[1]} />
}

function EnterpriseDisabledMessage() {
  return (
    <div className="border rounded-2 p-3 mb-3">
      <ShieldLockIcon className="v-align-middle mr-1" />
      <span className="mb-0">Custom models have been disabled by your enterprise policy administrators.</span>
    </div>
  )
}

try{ CustomModelsIndex.displayName ||= 'CustomModelsIndex' } catch {}
try{ CustomKeysTabs.displayName ||= 'CustomKeysTabs' } catch {}
try{ AddCustomKeyButtonShowRoute.displayName ||= 'AddCustomKeyButtonShowRoute' } catch {}
try{ EnterpriseDisabledMessage.displayName ||= 'EnterpriseDisabledMessage' } catch {}