import type {CopilotForBusinessModelsPayload, CopilotForBusinessPoliciesPayload} from '../types'
import {useDebugValue} from 'react'

/**
 * Ensures an org name is present. The source of this may change in the future, but allows callsites to remain unaware.
 */
export function useEnsureOrgName(payload: CopilotForBusinessPoliciesPayload | CopilotForBusinessModelsPayload) {
  const org_name = payload.org_name
  useDebugValue(org_name)
  return org_name
}
