import {useQuery} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'

import type {CustomModelsIndexPayload} from '../types'

export function useCustomModelsQuery({org}: {org: string}) {
  const queryKey = ['byok-settings', 'customModels', org]
  const query = useQuery({
    queryKey,
    queryFn: async (): Promise<CustomModelsIndexPayload> => {
      const response = await verifiedFetch(`/organizations/${org}/settings/copilot/custom-models`, {
        headers: {Accept: 'application/json'},
      })
      if (!response.ok) {
        throw new Error(`Failed to fetch Copilot custom models for organization ${org}: ${response.status}`)
      }

      const result = await response.json()
      return (result.payload?.customModelsIndexRoute || result) as CustomModelsIndexPayload
    },
    enabled: org.trim().length > 0,
  })
  return {...query, queryKey}
}
