import {XCircleFillIcon} from '@primer/octicons-react'
import {Link, FormControl, TextInput, Button} from '@primer/react'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import type {CopilotMcpRegistryPolicy} from '../types'
import styles from '../routes/Policies.module.css'

export type McpRegistryProps = {
  mcpRegistry: CopilotMcpRegistryPolicy
  value: string
  onChange: (value: string) => void
  loading: boolean
  onSubmit: (e: React.FormEvent) => void
  inputDisabled: boolean
  onDelete: () => void
}

export default function McpRegistry({
  mcpRegistry,
  value,
  onChange,
  onSubmit,
  inputDisabled,
  onDelete,
}: McpRegistryProps) {
  const mcpDescriptionText = mcpRegistry.isGA
    ? 'MCP servers listed in this registry will be visible to members in Visual Studio Code.'
    : 'MCP servers listed in this registry will be visible to members. Note that the MCP registries are currently supported in VS Code only, with support for all Copilot IDEs coming soon.'
  return (
    <>
      <div data-testid={`cfb-policies-mcp-registry-feature`} className="ml-3" style={{maxWidth: 750}}>
        <PreviewFeatureHeading title={mcpRegistry.displayname} beta={false} />
        {'URL for a '}
        <Link inline href="https://github.com/modelcontextprotocol/registry">
          specification-compliant
        </Link>
        {` MCP registry. ${mcpDescriptionText}`}
        <form id="mcp-registry-url" onSubmit={onSubmit} className="mt-2" data-testid="mcp-registry-form">
          <div style={{display: 'flex', alignItems: 'flex-end', gap: 8}}>
            <FormControl disabled={inputDisabled} className={styles.halfWidth}>
              <FormControl.Label visuallyHidden>MCP Registry URL</FormControl.Label>
              <TextInput
                block
                aria-label={mcpRegistry.displayname}
                name={mcpRegistry.displayname}
                value={value}
                placeholder="https://exampleregistry.com/allowed-servers"
                onChange={e => onChange(e.target.value)}
                type="url"
                trailingAction={
                  mcpRegistry.mcpRegistryUrl && !inputDisabled ? (
                    <TextInput.Action onClick={onDelete} icon={XCircleFillIcon} aria-label="Clear" />
                  ) : undefined
                }
              />
            </FormControl>
            <Button type="submit" disabled={inputDisabled} style={{marginTop: 8}}>
              Save
            </Button>
          </div>
        </form>
      </div>
    </>
  )
}

try{ McpRegistry.displayName ||= 'McpRegistry' } catch {}