import {Link} from '@primer/react'
import type {
  CopilotForBusinessGeneralPolicy,
  CopilotForBusinessModelsPayload,
  CopilotForBusinessPoliciesPayload,
} from '../types'
import {ShieldLockIcon} from '@primer/octicons-react'
import {ActionMenuButton} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import {useOptions} from '../hooks/use-options'

export default function GeneralPolicy({
  payload,
  policy,
}: {
  payload: CopilotForBusinessPoliciesPayload | CopilotForBusinessModelsPayload
  policy: CopilotForBusinessGeneralPolicy
}) {
  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: policy.options,
    controls: policy.manages,
    defaultOption: {
      value: 'NA',
      id: 'unconfigured',
      title: 'Unconfigured',
    },
  })

  const disabled = !policy.configurable

  if (!policy.visible) {
    return null
  }

  return (
    <>
      <div data-testid={`cfb-policies-${policy.manages}-feature`} style={{maxWidth: 750}}>
        <PreviewFeatureHeading title={policy.displayname} beta={policy.preview} />
        {policy.description}
        <br />
        {policy.helpurl && policy.helptext && (
          <Link href={policy.helpurl} inline>
            {policy.helptext}
          </Link>
        )}
      </div>
      {disabled ? (
        <span data-testid={`cfb-policies-${policy.manages}-feature-locked`}>
          <ShieldLockIcon /> {selected?.title ?? 'Disabled'}
        </span>
      ) : (
        <ActionMenuButton
          title={selected?.title ?? 'Disabled'}
          options={options}
          onSelect={onSelect}
          disabled={disabled}
          loading={loading}
          data-testid={`cfb-policies-${policy.manages}-control`}
        />
      )}
    </>
  )
}

try{ GeneralPolicy.displayName ||= 'GeneralPolicy' } catch {}