import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useQuery} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {useCurrentOrg} from '../contexts/CurrentOrgContext'
import {getMaybeJSONErrorMessage} from '../helpers/extract-errors'
import type {Provider} from '../providers/config'
import type {SelectorCustomModel} from '../types'

export function useFetchProviderModels<P = Provider>({
  apiKey,
  provider,
  customKeyId,
  deploymentUrl,
  enabled,
}: {
  apiKey?: string
  provider: P
  customKeyId?: number
  deploymentUrl?: string
  enabled: boolean
}) {
  const additionalFields = {
    custom_key_id: customKeyId,
    deployment_url: deploymentUrl,
  }
  const org = useCurrentOrg()
  const queryKey = ['byok-settings', 'availableModels', org, provider, apiKey, additionalFields]

  const query = useQuery({
    queryKey,
    initialData: [],
    gcTime: 1 * 60 * 1000, // 1 minute
    enabled,
    async queryFn({signal}) {
      const r = await reactFetchJSON(
        `/organizations/${org}/settings/copilot/custom-models/${provider as string}/models`,
        {
          method: 'POST',
          signal,
          body: {
            api_key: apiKey,
            ...additionalFields,
          },
        },
      )

      if (!r.ok) {
        const errorMessage = await getMaybeJSONErrorMessage(r)
        throw new ResponseError(errorMessage ?? 'Failed to fetch available models', r)
      }

      return (await r.json()) as SelectorCustomModel[]
    },
  })

  return {...query, queryKey}
}
