import {useState, useCallback} from 'react'
import {useOptions} from '../hooks/use-options'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {CopilotForBusinessPoliciesPayload} from '../types'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import type {BannerProps} from '@primer/react/experimental'

// MCP Policy is the primary policy - it has the general policy options (enabled, disabled, no policy)
// MCP Registry is a secondary policy that allows customers to configure a MCP Registry URL
// MCP Registry Access is a tertiary policy that allows customers to configure access to the MCP Registry
export function useMcpPolicyState(payload: CopilotForBusinessPoliciesPayload) {
  const mcpPolicyOptions = useOptions(payload, {
    items: payload.mcp.options,
    controls: payload.mcp.manages,
    defaultOption: {
      value: 'NA',
      id: 'unconfigured',
      title: 'Unconfigured',
    },
  })

  const mcpRegistryAccessOptions = useOptions(payload, {
    items: payload.mcp_registry_access.options || [],
    controls: payload.mcp_registry_access.manages,
  })

  const [registryUrl, setRegistryUrl] = useState(payload.mcp_registry.mcpRegistryUrl || '')
  const [registryAccess, setRegistryAccess] = useState(mcpRegistryAccessOptions.selected)
  const [loading, setLoading] = useState(false)
  const [bannerMessage, setBannerMessage] = useState<{message?: string; variant?: BannerProps['variant']}>({})
  const mcpPolicyDisabled = mcpPolicyOptions.selected?.value !== 'enabled'

  const updateRegistryAccessOptions = (selectedOption: ActionMenuButtonOption) => {
    mcpRegistryAccessOptions.setOptions(prev => {
      return prev.map(option => {
        option.selected = selectedOption.id === option.id
        return option
      })
    })
  }

  const handleRegistryUrlChange = useCallback((url: string) => {
    setRegistryUrl(url)
  }, [])

  const submitRegistryUrl = (urlOverride?: string) => {
    submitMcpRegistry(urlOverride ?? registryUrl, registryAccess?.value)
  }

  const submitRegistryAccess = async (option: ActionMenuButtonOption) => {
    await submitMcpRegistry(registryUrl, option.value)
    setRegistryAccess(option)
    updateRegistryAccessOptions(option)
  }

  const submitMcpRegistry = async (registryUrlValue: string | null, registryAccessValue: string | unknown) => {
    setLoading(true)
    setBannerMessage({})
    try {
      const response = await verifiedFetchJSON(payload.mcp_registry.submitPath, {
        method: 'PUT',
        body: {
          id: payload.mcp_registry.mcpRegistryId,
          registry_url: registryUrlValue,
          registry_access: registryAccessValue,
        },
      })
      if (response.ok) {
        setBannerMessage({
          message: 'MCP registry updated successfully.',
          variant: 'success',
        })
      } else {
        const error = await response.json()
        setBannerMessage({
          message: error.message || 'Failed to update MCP registry.',
          variant: 'critical',
        })
      }
    } catch (e: unknown) {
      let message = 'Failed to update MCP registry.'
      if (e instanceof Error) message = e.message
      setBannerMessage({message, variant: 'critical'})
    } finally {
      setLoading(false)
    }
  }

  const dismissBanner = () => setBannerMessage({})

  return {
    mcpOptions: mcpPolicyOptions,
    mcpRegistryAccessOptions,
    registryUrl,
    setRegistryUrl: handleRegistryUrlChange,
    registryAccess,
    loading,
    bannerMessage,
    dismissBanner,
    mcpPolicyDisabled,
    submitRegistryUrl,
    submitRegistryAccess,
  }
}
